internal object DuaUkDraft4 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rooster_donkey" to DuaText("Почути півня чи осла", "О Аллах, я прошу Тебе про Твою щедрість (півень). — Я вдаюся до Аллаха від шайтана, проклятого (осла).", "Почувши, як півень просить щедрості Аллаха; почувши рев осла, шукайте притулку від шайтана.", "Півень бачить ангела, а осел диявола."),
        "dua_something_liked" to DuaText("Побачити щось чудове (від лихого ока)", "Що побажав Аллах. О Аллах, благослови це.", "Побачивши щось чудове, що належить комусь, моліться про благословення.", "Молитва про благословення запобігає пристріт."),
        "dua_sell_buy_debt_repaid" to DuaText("При погашенні боргу", "Нехай Аллах благословить вас у вашій родині та вашому багатстві.", "Для кредитора при поверненні боргу.", "Повернення за позику - це подяка та повернення."),
        "dua_talbiyah" to DuaText("Талбія", "Ось я, о Аллах, ось я. Ось я, у вас немає партнера, ось я. Напевно, вся хвала, благословення та влада належать Вам. У вас немає партнера.", "Вголос після входу в іхрам.", "Емблема хаджу та умри."),
        "dua_yamani_hajar" to DuaText("Між Рукн Ямані та Хаджар Асвад", "Господи наш, дай нам добра в цьому світі і добра в потойбічному світі, захисти нас від кари вогню.", "У тавафі між Єменським кутом і Чорним каменем.", "Пророк ﷺ прочитав це на цьому місці в тавафі."),
        "dua_safa_marwa" to DuaText("На Сафа і Марва", "Ніхто не гідний поклоніння, крім Аллаха, єдиного, без партнера. Його влада і хвала, і Він має владу над усім. Ніхто не гідний поклоніння, крім одного Аллаха; Він виконав Свою обітницю, допоміг Своєму слузі і самотужки переміг союзників.", "Підйом на Сафу і обличчям до Кібли (тричі).", "Зікр Пророка ﷺ на Сафа і Марва."),
        "dua_arafah" to DuaText("Найкраща дуа дня Арафа", "Ніхто не гідний поклоніння, крім Аллаха, єдиного, без партнера. Його влада і хвала, і Він має владу над усім.", "День Арафа — найкраща дуа.", "Найкраща дуа - це дуа Дня Арафа, а найкращі слова - це."),
        "dua_takbeer_tashreeq" to DuaText("Такбір-е-Ташрик", "Аллах найбільший, Аллах найбільший. Немає бога, крім Аллаха. Аллах є найбільшим, Аллах є найбільшим, і вся хвала Аллаху.", "Після кожної обов'язкової молитви від Фаджру 9 зуль-хіджа до Аср 13 зуль-хіджа.", "Передано від Алі та Ібн Масуда (RA) — ваджиб за ханафітами."),
        "dua_zamzam" to DuaText("Пити Замзам", "О Аллах, я прошу Тебе про благодатне знання, рясне забезпечення і ліки від усіх хвороб.", "Коли ви п'єте замзам, робіть дуа для будь-якого наміру.", "Замзам призначений для того, заради чого його п'ють (Ібн Маджа 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Роздуми про створення", "Господи наш, Ти не надаремно все це створив. Слава Тобі, захисти нас від кари Вогню.", "Дуа тих, хто розмірковує про створення небес і землі.", "Дуа людей розуміння (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Ми почули закликаючого до віри", "Господи наш, ми почули, як хтось закликав до віри, кажучи: «Віруйте у свого Господа», і ми увірували. Our Lord, forgive us our sins, remove from us our misdeeds and cause us to die with the righteous.", "Дуа за віру і смерть серед праведних.", "Дуа про прощення та гарний кінець."),
        "dua_q_atina_ma_waadtana" to DuaText("Виконайте те, що ви обіцяли", "Господи наш, даруй нам те, що Ти обіцяв нам через Своїх посланців, і не зганьби нас у День Воскресіння. Дійсно, Ти не порушуєш своєї обіцянки.", "Притулок від ганьби в День Воскресіння.", "Шукаючи шани в потойбіччі."),
        "dua_q_israfana" to DuaText("Пробачте наші надмірності", "Господи наш, прости нам наші гріхи і наші надмірності в наших справах, утверди наші ноги і допоможи нам проти невіруючих.", "Дуа сподвижників попередніх пророків.", "Дуа за стійкість і прощення."),
        "dua_q_jamiun_nas" to DuaText("Ти збереш людство", "Господи наш, Ти напевно збереш людство в День, в якому немає сумнівів. Воістину, Аллах не порушує Свою обіцянку.", "Підтвердження впевненості в Дні Воскресіння.", "Дуа тих, хто міцно ґрунтується на знаннях."),
        "dua_q_maash_shahidin" to DuaText("Напишіть нас серед свідків", "Господи наш, ми увірували, тож запиши нас серед свідків.", "Дуа тих, хто визнав правду і повірив.", "Дуа для прийняття своєї віри."),
        "dua_q_la_tajalna_zalimin" to DuaText("Не з грішниками", "Господи наш, не поміщай нас до грішників.", "Дуа народу аль-А'раф.", "Притулок від долі кривдників."),
        "dua_q_tawaffana_muslimin" to DuaText("Терпіння і смерть як мусульмани", "Господи наш, вилий на нас терпіння і зроби так, щоб ми померли як мусульмани.", "Дуа магів фараона, коли вони повірили.", "Терпіння у випробуваннях і кінець на вірі."),
        "dua_q_la_tajalna_fitnah" to DuaText("Не суд над гнобителями", "Ми покладаємося на Аллаха. Господи наш, не влаштуй нас випробуванням для грішників і спаси нас Своєю милістю від невіруючих.", "Дуа народу Муси (AS).", "Дуа для порятунку від гніту і гнобителів."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Дуа Нуха (AS) для прощення", "Мій Господи, я шукаю притулку в Тебе, щоб не просити Тебе про те, про що я не знаю. І якщо Ти не пробачиш мене і не помилуєш мене, я буду серед переможених.", "Дуа покаяння пророка Нуха (AS).", "Урок запитувати з належними манерами."),
        "dua_q_mudkhala_sidq" to DuaText("Вхід і вихід Істини", "Мій Господи, зроби так, щоб я увійшов з істиною і вийшов з істиною, і дай мені від Себе підтримку.", "Перед введенням нового завдання, дому чи місця.", "Дуа, яку вчили Пророку ﷺ під час Хіджри."),
        "dua_q_la_tadharni_fardan" to DuaText("Дуа Закарії (AS) — Не залишай мене одного", "Мій Господи, не залишай мене самого, і Ти найкращий із спадкоємців.", "Для тих, хто шукає дітей.", "Через це дуа Аллах дарував Ях'ї (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Благословенне місце приземлення", "Мій Господи, дай мені приземлитися на благословенному місці, а Ти найкращий з тих, хто виводить на землю.", "При переїзді в новий дім або зупинці десь — дуа Нуха (AS).", "Дуа для благословення на новому місці."),
        "dua_q_amanna_faghfir" to DuaText("Ми віримо, тому вибач нас", "Господи наш, ми увірували, тож прости нас і помилуй нас, а Ти найкращий із милосердних.", "Дуа праведних рабів Аллаха.", "Всеосяжна дуа про прощення та милосердя."),
        "dua_q_isrif_jahannam" to DuaText("Відвернути кару пекла", "Господи наш, відверни від нас кару пекла; справді його покарання вічне. Воістину, це зле поселення і оселя.", "Дуа слуг Всемилостивого ('Ібад ар-Рахман).", "Коранічне дуа для притулку від пекла."),
        "dua_q_hab_li_hukman" to DuaText("Дуа Ібрагіма (AS) — Мудрість і Джанна", "Мій Господи, дай мені мудрість і приєднай мене до праведних, дай мені почесну згадку серед наступних поколінь і зроби мене серед спадкоємців Саду Блаженства.", "Просячи мудрості, товариства праведних і раю.", "Повна дуа Ібрагіма (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Дуа Лута (AS) — Врятуй мою родину", "Мій Господи, врятуй мене і мою сім'ю від (наслідків) того, що вони роблять.", "Захист своєї родини від зла.", "Захист сім'ї від зла."),
        "dua_q_sulaiman_awzini" to DuaText("Дуа Сулеймана (AS) на знак подяки", "Мій Господи, дай мені бути вдячним за Твою милість, яку Ти обдарував мене і моїх батьків, і робити праведні вчинки, які приємні Тобі, і допусти мене своєю милістю до Твоїх праведних рабів.", "За вміння бути вдячним за блага.", "Дуа подяки Сулеймана (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Дуа Муси (AS) — Я образив себе", "Мій Господи, я образив себе, тож вибач мене.", "Негайне каяття після помилки.", "Аллах простив Мусу (AS)."),
        "dua_q_musa_najjini" to DuaText("Дуа Муси (AS) — Врятуй мене від гнобителів", "Мій Господи, врятуй мене від людей несправедливих.", "Коли боїться гнобителів.", "Дуа Муси (AS) при виїзді з Єгипту."),
        "dua_q_lut_unsurni" to DuaText("Дуа Люта (AS) — Допомога проти корупціонерів", "Мій Господи, допоможи мені проти розбещених людей.", "За допомогу тим, хто поширює корупцію.", "Дуа тих, хто твердо стоїть на правді."),
        "dua_q_hab_li_salihin" to DuaText("Дуа Ібрагіма (AS) для праведної дитини", "Мій Господи, даруй мені (дитину) з числа праведних.", "Прохання про праведних дітей.", "Через цю дуа Ісмаїлу було даровано (AS)."),
        "dua_q_wasita_kulla_shay" to DuaText("Дуа ангелів, що несуть трон", "Господи наш, Ти охоплюєш усе милосердям і знанням, тому прости тих, хто кається і йде Твоїм шляхом, і захисти їх від кари пекла.", "Ангели, які несуть Престол, роблять цю дуа для віруючих.", "Декламується з наміром бути включеним до дуа ангелів."),
        "dua_q_ikhwanina" to DuaText("Для наших братів, які були перед нами", "Господи наш, прости нас і наших братів, які попередили нас у вірі, і не вклади в наші серця образи на віруючих. Господи наш, Ти воістину добрий і милосердний.", "Дуа за віруючих, що прийшли раніше, і за чисте серце.", "Дуа для благородних сподвижників (RA) і ранніх віруючих."),
        "dua_q_alayka_tawakkalna" to DuaText("Ми покладаємось на вас (Ібрагім А.С.)", "Господи наш, на Тебе ми покладаємося, до Тебе ми звертаємось і до Тебе повернення. Господи наш, не роби нас випробуванням для невіруючих і прости нас. Господи наш, Ти воістину Всемогутній, Мудрий.", "Дуа Ібрагіма (AS) і його сподвижників.", "Дуа покладатися на Аллаха і звертатися до Нього."),
        "dua_q_atmim_nurana" to DuaText("Удосконалюйте наше світло", "Господи наш, удосконали для нас наше світло і прости нас. Дійсно, Ти маєш владу над усім.", "Дуа віруючих у День Воскресіння.", "Просячи світла на Сірат."),
        "dua_q_asiya_baytan" to DuaText("Дуа Асії — Будинок у Джанні", "Мій Господи, побудуй мені біля Тебе дім у раю, врятуй мене від фараона і його вчинків, і врятуй мене від людей несправедливих.", "Дуа Асії, дружини фараона.", "Аллах зробив її прикладом для віруючих."),
        "dua_adhan_response" to DuaText("Відповідь на азан", "Немає ніякої могутності та влади, окрім Аллаха.", "Повторіть те, що говорить муедзин; в «Хайя алас-салах» і «Хайя алаль-фалах» кажуть це.", "Хто відгукнеться серцем, той увійде в рай."),
        "dua_adhan_shahadah" to DuaText("Після шахади Муаззина", "And I too bear witness that none has the right to be worshipped except Allah, alone, without partner, and that Muhammad ﷺ is His servant and Messenger. Я задоволений Аллахом як Господом, Мухаммедом ﷺ як Посланцем і ісламом як релігією.", "Вислухавши свідчення віри муедзина.", "Його гріхи прощені."),
        "dua_istiftah_baid" to DuaText("Початкова дуа: Відстань мене від гріхів", "О Аллах, віддали мене від моїх гріхів, як Ти віддалив схід від заходу. О Аллах, очисти мене від гріхів, як білий одяг очищається від бруду. О Аллах, змий мої гріхи водою, снігом і градом.", "Після вступного такбіру (можна також сказати замість Сани).", "Пророк ﷺ прочитав це між такбіром і читанням."),
        "dua_hamdan_kathiran" to DuaText("Рясна похвала після Руку", "Господи наш, Тобі належить хвала — рясна, чиста і благословенна хвала.", "Після підйому з руки разом з «Раббана лакал-хамд».", "Більше тридцяти янголів змагалися, хто першим запише це."),
